P={1:("네트워크 기초 표지",["Network"],"네트워크 기초 강의 표지이다.","cover"),2:("강의 목차",["Network","IP","NAT","DNS","HTTP","Security"],"네트워크, IP·NAT, DNS·HTTP, 보안 순으로 구성된다.","table_of_contents"),3:("컴퓨터 네트워크 시작",["Network"],"네트워크 시작 섹션이다.","section_divider"),4:("컴퓨터 네트워크",["host","network device","link","message"],"네트워크는 호스트와 중간 장비가 링크로 연결되어 메시지를 주고받는 통신망이다.","core_content"),5:("LAN과 WAN",["LAN","WAN","ISP"],"LAN은 가까운 범위를 조직이 관리하고 WAN은 먼 지역을 연결하며 주로 ISP가 관리한다.","core_content"),6:("패킷 교환",["packet","router","switch"],"메시지를 작은 패킷으로 나눠 보내며 라우터·스위치가 수신지와 경로를 판단한다.","core_content"),7:("네트워크 참조 모델",["layer","reference model"],"통신 과정을 계층화하면 설계와 문제 진단이 쉬워진다.","core_content"),8:("IP와 NAT",["IP","NAT"],"IP와 NAT 섹션이다.","section_divider"),9:("프로토콜·IP·ARP",["protocol","IP","ARP","MAC"],"프로토콜은 합의된 통신 규칙이며 IP는 패킷 전달, ARP는 IP와 MAC 대응에 쓰인다.","core_content"),10:("IP 주소와 Port",["IPv4","IPv6","port","HTTP","HTTPS","SSH"],"IP는 호스트 주소, port는 호스트 안의 애플리케이션 프로세스를 식별한다.","core_content"),11:("NAT",["NAT","private IP","public IP","IPv4 exhaustion"],"NAT는 내부 사설 IP와 외부 공인 IP를 변환해 제한된 IPv4 공인 주소를 공유하게 한다.","core_content"),12:("공인 IP 할당",["public IP","ISP"],"공인 IP는 ISP나 공인 할당 기관을 통해 할당받는다.","supplementary_reference"),13:("Port Forwarding",["port forwarding","host","port"],"외부 IP·포트로 온 패킷을 내부의 지정 호스트·포트로 전달한다.","core_content"),14:("TCP와 UDP",["TCP","UDP","connection","reliability"],"TCP는 연결·순서·재전송으로 신뢰성을 높이고 UDP는 연결 없이 더 빠르지만 보장이 적다.","core_content"),15:("IP·MAC 실습",["ipconfig","ifconfig","IPv4","MAC"],"활성 인터페이스의 IPv4와 MAC 주소를 확인한다.","example"),16:("Port 실습",["netstat","LISTENING","ESTABLISHED","PID"],"열린 포트와 연결 상태·상대 주소·PID를 확인한다.","example"),17:("DNS와 HTTP",["DNS","HTTP"],"DNS와 HTTP 섹션이다.","section_divider"),18:("DNS와 Domain",["client","server","domain","DNS","IP"],"DNS는 사람이 읽는 도메인 이름을 서버 IP 주소로 변환한다.","core_content"),19:("HTTP",["HTTP","TCP","request","response","status","header","body"],"HTTP는 TCP 위에서 요청·응답으로 웹 데이터를 교환하며 응답은 상태·헤더·본문을 담는다.","core_content"),20:("요청 흐름",["DNS","IP","port","TCP","HTTP"],"도메인 요청은 DNS 해석, IP·port 결정, TCP 연결, HTTP 교환, 서버 응답 순으로 진행된다.","core_content"),21:("네트워크 보안",["Security"],"네트워크 보안 섹션이다.","section_divider"),22:("대칭키 암호화",["key","symmetric encryption"],"대칭키는 암호화와 복호화에 같은 키를 써 빠르지만 안전한 키 공유가 어렵다.","core_content"),23:("공개키와 세션키",["public key","private key","session key"],"공개키 방식은 키 공유에 유리하지만 느려 대칭 세션키와 결합한다.","core_content"),24:("인증서와 디지털 서명",["certificate","CA","digital signature"],"CA 인증서는 공개키 유효성을 증명하고 디지털 서명은 개인키·공개키로 신원을 검증한다.","core_content"),25:("HTTPS·SSL·TLS",["HTTPS","SSL","TLS","certificate"],"HTTPS는 인증서·공개키·대칭키를 결합한 TLS 위에서 HTTP를 보호한다.","core_content"),26:("실습",["Network lab"],"네트워크 실습 섹션이다.","section_divider"),27:("요청 흐름 실습",["private IP","DNS","TCP","HTTP","load balancing"],"사설 IP, DNS 다중 주소, TCP 연결 시간과 HTTP 200 응답을 관찰한다.","example"),28:("강의 마무리",["Network"],"네트워크 기초 종료 페이지이다.","closing")}
