UNITS=[U("net_p4",4,"definition","여러 장치가 그물처럼 연결 / 호스트·네트워크 장비·통신 매체·메세지","네트워크 구성요소를 역할별로 구분한다.",["network","host","node","link","message"]),U("net_p5",5,"comparison","LAN: 가까운 지역·개발자 관리 / WAN: 먼 지역·ISP 관리","LAN과 WAN은 범위와 관리 주체가 다르다.",["lan","wan","isp"]),U("net_p6",6,"procedure","메세지를 패킷으로 쪼개 송수신 / 라우터·스위치가 경로·송수신지 식별","패킷 교환은 분할 전송과 중간 장비 전달로 동작한다.",["packet","packet_switching","router","switch"]),U("net_p7",7,"interpretation","통신 과정을 계층으로 나누면 구성·설계·문제 진단과 해결이 용이","계층화는 복잡성을 분리한다.",["reference_model","layer"]),U("net_p9",9,"definition","프로토콜은 합의된 규칙 / IP는 패킷 전달 / ARP는 IP 주소를 MAC 주소로 대응","프로토콜별 역할이 다르다.",["protocol","ip","arp","ip_address","mac_address"]),U("net_p10",10,"comparison","IP 주소는 네트워크 고유 주소 / Port는 애플리케이션 프로세스 식별 / IPv4 고갈·IPv6","주소와 포트, IP 버전을 구분한다.",["ip_address","ipv4","ipv6","port"]),U("net_p11",11,"definition","사설 IP를 외부 통신 시 공인 IP로 변환 / IPv4 주소 고갈","NAT는 주소 변환과 공인 주소 공유를 제공한다.",["nat","private_ip","public_ip","ipv4"]),U("net_p13",13,"definition","특정 호스트에 IP 주소와 포트 번호를 할당하고 해당 호스트에게 패킷 전달","포트 포워딩은 외부 포트를 내부 목적지로 매핑한다.",["port_forwarding","host","port","packet"]),U("net_p14",14,"comparison","TCP 연결 O·신뢰성 높음·상대적으로 느림 / UDP 연결 X·신뢰성 낮음·빠름 / TCP 순서·재전송","TCP와 UDP의 연결·신뢰성·속도 trade-off가 다르다.",["tcp","udp","connection","retransmission"]),U("net_p18",18,"definition","Domain Name은 IP 주소와 대응되는 문자열 / DNS는 도메인을 IP로 변환","DNS는 이름을 주소로 해석한다.",["dns","domain_name","ip_address"]),U("net_p18b",18,"relation","클라이언트 요청, 서버 응답","네트워크 애플리케이션은 요청·응답으로 상호작용한다.",["request","response"]),U("net_p19",19,"definition","HTTP는 TCP 연결 위의 애플리케이션 계층 프로토콜 / Request↔Response / Status·Headers·Body","HTTP는 TCP 위에서 구조화된 웹 메시지를 교환한다.",["http","tcp","request","response","status_code","header","body"]),U("net_p20",20,"procedure","도메인→DNS→IP 주소·포트→TCP 연결→HTTP 교환→서버 응답","요청은 이름 해석부터 전송 연결과 애플리케이션 교환으로 이어진다.",["domain_name","dns","ip_address","port","tcp","http","response"]),U("net_p27",27,"example","IP가 여러 개 나오는 이유: 트래픽 분산, 장애 대비","한 도메인은 가용성과 부하 분산을 위해 여러 IP로 해석될 수 있다.",["dns","ip_address"]),U("net_p22",22,"definition","암호화와 복호화에 동일한 키 / 안전하게 키 공유하기 어려움","대칭키는 빠르지만 키 배송 문제가 있다.",["symmetric_key"]),U("net_p23",23,"comparison","대칭키는 빠르나 키 전송 어려움 / 공개키는 느리나 키 안전 공유 / 세션 키","실제 보안 통신은 공개키로 세션키를 교환하고 대칭키로 데이터를 처리한다.",["symmetric_key","asymmetric_key","public_key","private_key","session_key"]),U("net_p24",24,"definition","공개키 인증서는 공개키 유효성을 입증 / CA 서명으로 검증 / 디지털 서명은 개인키와 공개키로 신원 증명","인증서와 서명은 공개키의 주체와 메시지 출처를 검증한다.",["certificate","ca","digital_signature","public_key","private_key"]),U("net_p25",25,"relation","대칭키·공개키·인증서를 기반으로 SSL/TLS / HTTPS는 HTTP over TLS","HTTPS는 TLS로 HTTP 통신을 암호화·인증한다.",["symmetric_key","asymmetric_key","certificate","ssl","tls","https","http"])]

