def apply_evaluation_data(processed_path=PROCESSED_PATH,rubric_path=RUBRIC_PATH):
 d=json.loads(Path(processed_path).read_text()); pages={x["page"]:x for x in d["chunks"]}; d["schema_version"]="2.1.0"; d["terminology"]=TERMINOLOGY
